 "content": "def transform(grid):
    # Translate the nonzero pattern associated with one 5-marker to the other.
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(pts) != 2:
        return [row[:] for row in grid]
    # The motif is the nonzero cluster connected or adjacent to the first marker;
    # choose marker whose neighborhood participates in the denser motif.
    def near(p):
        r,c=p
        return sum(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] != 0
                   for dr in range(-2,3) for dc in range(-2,3))
    src, dst = sorted(pts, key=near, reverse=True)
    sr, sc = src
    # Identify all nonzero cells in local motif bounded by a 5x5 neighborhood.
    motif=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and max(abs(r-sr),abs(c-sc)) <= 3:
                motif.append((r,c,grid[r][c]))
    out=[row[:] for row in grid]
    dr,dc=dst[0]-sr,dst[1]-sc
    for r,c,v in motif:
        rr,cc=r+dr,c+dc
        if 0<=rr<h and 0<=cc<w and v != 5:
            out[rr][cc]=v
    out[dst[0]][dst[1]]=0
    return out

